    $originalControl.find('.help-box, .clearfix').hide();
    $originalControl.css({ marginBottom: 0, paddingBottom: 0 });
    $originalControl.find('.form-group, .control-input-wrapper, .control-input').css({
        marginBottom: 0,
        paddingBottom: 0,
    });

    return filterWrapper;
}

