// Основной скрипт - ОПТИМИЗИРОВАННАЯ ВЕРСИЯ БЕЗ CSS В JS
let projectsWorkloadStickyDataTablePromise = null;

function loadScript(url) {
    return new Promise((resolve, reject) => {
        const existing = document.querySelector(`script[src="${url}"]`);
        if (existing) {
            existing.addEventListener('load', resolve, {once: true});
            existing.addEventListener('error', reject, {once: true});
            if (window.StickyDataTable) resolve();
            return;
        }

        const script = document.createElement('script');
        script.src = url;
        script.onload = resolve;
        script.onerror = reject;
        document.body.appendChild(script);
    });
}

function ensureProjectsWorkloadStickyDataTable() {
    if (window.StickyDataTable) {
        return Promise.resolve();
    }

    if (!projectsWorkloadStickyDataTablePromise) {
        projectsWorkloadStickyDataTablePromise = loadScript("/assets/dinext_common/js/sticky-datatable.js").then(() => {
            if (!window.StickyDataTable) {
