function isNonWorkingDay(date, holidays) {
    if (!date || !holidays || holidays.length === 0) {
        return false;
    }

    const targetDateStr = date;

    for (let i = 0; i < holidays.length; i++) {
        const holiday = holidays[i];
        if (holiday.date === targetDateStr) {
            return true;
        }
    }

    return false;
}

