 */
function createProjectFilterRow(frm, $wrapper) {
    let controls = $('<div class="projects-workload-controls unified-filters-row"></div>').appendTo($wrapper);

    let filtersContainer = $('<div class="filters-container"></div>').appendTo(controls);

    // Гарантируем, что даты инициализированы
    ensureDatesInitialized();

    // Дропдаун типа отображения (дни/недели/месяцы)
    const viewTypeControl = createViewTypeDropdown(filtersContainer);

    // НОВОЕ: Дропдаун периода отображения (квартал/полгода/год)
    const periodRangeControl = createPeriodRangeDropdown(filtersContainer);

    // Разделитель
    $('<div class="filter-separator"></div>').appendTo(filtersContainer);

    // Кнопки
    let buttonsContainer = $('<div class="filter-buttons"></div>').appendTo(filtersContainer);

    // Кнопка обновления
    let refreshBtn = $(`
        <button class="btn btn-default btn-sm" title="${__('Refresh Data')}">
            ↻
        </button>
    `).appendTo(buttonsContainer);

    refreshBtn.on('click', function() {
        if (WL_DEBUG) console.log('Manual refresh triggered');

        // Очищаем кэш
        projectWorkloadCache = {
            globalCache: {}
        };

        // Сбрасываем метаданные
        window.projectWorkloadMetadata = {};

        // также очищаем индекс
        window.projectWorkloadIndexed = null;

        // Загружаем данные с принудительным обновлением
        debouncedLoadProjectWorkloadData(frm, true, true);
    });

    return controls;
}

